CREATE TABLE IF NOT EXISTS lattis_commerce_sale (sale_id char(36) PRIMARY KEY, currency char(3) NOT NULL, scale smallint NOT NULL CHECK (scale BETWEEN 0 AND 3), total_minor bigint NOT NULL CHECK (total_minor > 0), snapshot_sealed mediumtext NOT NULL, snapshot_digest char(64) NOT NULL, status varchar(20) NOT NULL CHECK (status IN ('OPEN','CANCELLED','CLOSED')), fulfillment_status varchar(20) NOT NULL CHECK (fulfillment_status IN ('UNFULFILLED','PARTIAL','FULFILLED')), version int NOT NULL CHECK (version > 0), created_by varchar(191) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS lattis_commerce_link (sale_id char(36) NOT NULL, kind varchar(20) NOT NULL CHECK (kind IN ('payment','invoice','fulfillment','other')), provider varchar(64) NOT NULL, reference varchar(191) NOT NULL, provider_id varchar(191) NULL, status varchar(32) NOT NULL, amount_minor bigint NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (kind,provider,reference), UNIQUE KEY lattis_commerce_link_provider_id (kind,provider,provider_id), KEY lattis_commerce_link_sale (sale_id,kind), FOREIGN KEY (sale_id) REFERENCES lattis_commerce_sale(sale_id));
